<script setup lang="ts">
/**
 * An Input preset for searching (`design/components/search-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/search-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef } from 'vue'

import { agentFill, agentMember } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/search-input.module.css'
import Input from './Input.vue'
import Kbd from '../structure/Kbd.vue'

export interface SearchInputProps {
  ariaDescribedby?: string
  /**
   * Required unless a FormField supplies a label. Search boxes rarely have visible labels.
   */
  ariaLabel?: string
  /**
   * Names the field from a label elsewhere on the page, such as `SettingsRow`'s row label, which
   * is one label for a whole row rather than one per control.
   */
  ariaLabelledby?: string
  /**
   * The clear button's accessible name, passed to Input. Defaults to `Clear`.
   */
  clearLabel?: string
  defaultValue?: string
  disabled?: boolean
  id?: string
  name?: string
  placeholder?: string
  /**
   * A hint such as `⌘K`. Display only. Menu's `kbd` rule applies here too, and the vocabulary
   * never binds a global shortcut.
   */
  shortcut?: string
  size?: 'sm' | 'md' | 'lg'
  value?: string
}

defineOptions({ name: 'SearchInput', inheritAttrs: false })

const props = withDefaults(defineProps<SearchInputProps>(), {
  disabled: false,
  placeholder: 'Search…',
  size: 'md',
})
const emit = defineEmits<{ change: [value: string] }>()
const focused = ref(false)
const mirror = ref(props.defaultValue ?? '')
const frame = useTemplateRef<HTMLElement>('frame')
const current = computed(() => props.value ?? mirror.value)
const showShortcut = computed(
  () => props.shortcut !== undefined && current.value === '' && !focused.value && !props.disabled,
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'SearchInput',
    element: () => frame.value?.querySelector('input'),
    state: () => ({ value: current.value, disabled: props.disabled }),
    actions: {
      fill: {
        argument: 'text',
        run: (value) => agentFill(frame.value?.querySelector('input'), value),
      },
      clear: () => agentFill(frame.value?.querySelector('input'), ''),
    },
    withholds: () => frame.value,
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <span
    ref="frame"
    :class="styles.search"
    :data-shortcut="showShortcut ? '' : undefined"
    data-member="search-input"
    @focusin="focused = true"
    @focusout="focused = false"
  >
    <Input
      type="search"
      icon="search"
      :clearable="true"
      :clearLabel="clearLabel"
      :size="size"
      :disabled="disabled"
      :value="value"
      :defaultValue="defaultValue"
      :placeholder="placeholder"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="ariaDescribedby"
      :id="id"
      :name="name"
      @change="((mirror = $event), emit('change', $event))"
    >
      <template v-if="showShortcut" #trailing>
        <span :class="styles.hint" aria-hidden="true">
          <Kbd>
            {{ shortcut }}
          </Kbd>
        </span>
      </template>
    </Input>
  </span>
</template>
